int main(){nova::FitTarget t;t.note=57;t.tonal=true;t.gate=.7;t.left.resize(22050);t.right=t.left;
double frequencies[]={220,373.3,612.7,1120.5,1717.9,2831.1};
for(size_t i=0;i<t.left.size();++i){double time=i/t.rate,y=0;for(int j=0;j<6;++j)y+=.22/(j+1)*std::sin(2*nova::pi*frequencies[j]*time+j*.3)*std::exp(-time*(1+j*.9))*(1-std::exp(-time*400));t.left[i]=t.right[i]=static_cast<float>(y);}
std::atomic<bool> stop{false};auto result=nova::fitParameters(t,nova::preset(0),180,stop);std::cout<<"valid="<<result.valid<<" engine="<<result.parameters.engine<<" initial="<<result.initialError<<" native="<<result.nativeError<<" partial="<<result.spectralError<<" final="<<result.bestError<<" count="<<(result.model?result.model->count:0)<<" type="<<result.profile.description<<'\n';
if(!result.valid||!result.model||result.bestError>=result.nativeError*.8||result.bestError>.04)return 1;
 nova::Engine renderer;renderer.configure(result.parameters);renderer.prepare(t.rate);renderer.setModel(result.model.get());std::vector<float> a(t.left.size()),b(a.size());nova::renderCandidate(renderer,result.parameters,t,a,b);auto before=a;
 auto changed=result.parameters;changed.partialGains.fill(0);changed.noise=0;changed.residual=0;changed.delay=changed.reverb=changed.chorus=0;renderer.configure(changed);renderer.reset();renderer.noteOn(1,t.note,1);renderer.render(a.data(),b.data(),static_cast<int>(a.size()));double energy=0;for(float v:a)energy+=v*v;if(energy>1e-12)return 2;
 auto invalid=*result.model;invalid.count=49;if(invalid.valid())return 3;invalid=*result.model;invalid.partials[0].frequency=std::numeric_limits<float>::quiet_NaN();if(invalid.valid())return 4;
 nova::SpectralModel sine;sine.count=1;sine.root=57;sine.duration=1;for(int i=0;i<nova::modelFrames;++i){sine.times[i]=i/static_cast<float>(nova::modelFrames-1);sine.partials[0].amplitude[i]=1;}sine.partials[0].frequency=220;
 nova::Params pure;pure.engine=1;pure.root=57;pure.cutoff=20000;pure.envAmount=pure.resonance=pure.delay=pure.reverb=0;pure.sustain=1;pure.attack=.001f;pure.master=-6;renderer.configure(pure);renderer.prepare(48000);renderer.setModel(&sine);renderer.noteOn(1,69,1);a.resize(24000);b.resize(a.size());renderer.render(a.data(),b.data(),static_cast<int>(a.size()));int crossings=0;for(size_t i=1;i<a.size();++i)if(a[i-1]<=0&&a[i]>0)++crossings;if(crossings<219||crossings>221)return 5;
 nova::FitTarget high;high.rate=44100;high.note=69;high.left.resize(22050);high.right=high.left;high.gate=.4;for(size_t i=0;i<high.left.size();++i)high.left[i]=high.right[i]=static_cast<float>(.2*std::sin(2*nova::pi*14000*i/high.rate));auto fullBand=nova::fitParameters(high,nova::preset(0),120,stop);if(!fullBand.valid||!fullBand.model||fullBand.comparison.sampleRate!=44100)return 6;bool foundHigh=false;for(int j=0;j<fullBand.model->count;++j)if(fullBand.model->partials[j].frequency>13000)foundHigh=true;if(!foundHigh)return 7;std::cout<<"Full-band: native="<<fullBand.nativeError<<" partial="<<fullBand.spectralError<<"\n";
 std::cout<<"PASS: additive improves inharmonic test, 48 gain controls, invalid model rejection, procedural octave transposition ("<<crossings<<" cycles)\n";return 0;}
